def __validate_username(username: str):
    assert username is not None and len(username
        ) > 0, 'Username cannot be null or empty'
    assert isinstance(username, str), 'Username must be a string.'
    assert len(username
        ) <= 16, 'Usernames cannot be longer than 16 characters.'
    assert all([(c.isalnum() or c in ('_', '-')) for c in username]
        ), 'Username has invalid characters. Each character must be alphanumeric, a hyphen, or an underscore.'
    assert username[0] not in ('-', '_') and username[-1] not in ('-', '_'
        ), 'Usernames cannot start or end with a hyphen or underscore.'


